'use client';

import React, { useEffect, useState } from 'react';

const svgCache = new Map<string, string>();

/**
 * Normalizes any uploaded SVG (including VTracer exports that only have
 * `width="..." height="..."` without a `viewBox`) by automatically injecting
 * `viewBox="0 0 W H"` and responsive sizing attributes so it scales cleanly
 * at any pixel height without clipping.
 */
function normalizeUploadedSvg(rawSvg: string, targetHeight: number): string | null {
  if (!rawSvg || !rawSvg.includes('<svg')) return null;

  const svgOpenMatch = rawSvg.match(/<svg\b([^>]*)>/i);
  if (!svgOpenMatch) return null;

  const attrs = svgOpenMatch[1];
  const widthMatch = attrs.match(/\bwidth=["']([0-9.]+)(?:px)?["']/i);
  const heightMatch = attrs.match(/\bheight=["']([0-9.]+)(?:px)?["']/i);
  const viewBoxMatch = attrs.match(/\bviewBox=["']([^"']+)["']/i);

  let viewBox = viewBoxMatch ? viewBoxMatch[1] : '';
  let aspect = 1;

  if (!viewBox && widthMatch && heightMatch) {
    const w = parseFloat(widthMatch[1]);
    const h = parseFloat(heightMatch[1]);
    if (w > 0 && h > 0) {
      viewBox = `0 0 ${w} ${h}`;
      aspect = w / h;
    }
  } else if (viewBox) {
    const parts = viewBox.trim().split(/[\s,]+/).map(Number);
    if (parts.length === 4 && parts[2] > 0 && parts[3] > 0) {
      aspect = parts[2] / parts[3];
    }
  }

  const computedWidth = Math.max(1, Math.round(targetHeight * aspect));

  // Strip old width/height/viewBox/style from opening <svg> tag and inject clean scaled attributes
  const cleanedAttrs = attrs
    .replace(/\bwidth=["'][^"']*["']/gi, '')
    .replace(/\bheight=["'][^"']*["']/gi, '')
    .replace(/\bviewBox=["'][^"']*["']/gi, '')
    .trim();

  const newOpenTag = `<svg ${cleanedAttrs} ${
    viewBox ? `viewBox="${viewBox}"` : ''
  } width="${computedWidth}" height="${targetHeight}" style="height:${targetHeight}px;width:auto;display:block" preserveAspectRatio="xMidYMid meet">`;

  return rawSvg.replace(/<svg\b[^>]*>/i, newOpenTag);
}

function useNormalizedBrandSvg(src: string, targetHeight: number): string | null {
  const [raw, setRaw] = useState<string | null>(() => svgCache.get(src) || null);

  useEffect(() => {
    let active = true;
    if (svgCache.has(src)) {
      setRaw(svgCache.get(src) || null);
      return;
    }
    fetch(src)
      .then((res) => (res.ok ? res.text() : null))
      .then((text) => {
        if (!active || !text || !text.includes('<svg')) return;
        svgCache.set(src, text);
        setRaw(text);
      })
      .catch(() => {
        // Fallback to inline SVG on error
      });
    return () => {
      active = false;
    };
  }, [src]);

  if (!raw) return null;
  return normalizeUploadedSvg(raw, targetHeight);
}

