interface BaleLogoProps {
  className?: string;
  height?: number;
}

/**
 * Official BALE System Wordmark / Logo.
 * Loads `/brand/bale-logo.svg` from `public/brand/bale-logo.svg` (automatically
 * adding `viewBox` if omitted by VTracer and scaling to `height` px).
 */
export const BaleLogo: React.FC<BaleLogoProps> = ({
  className = '',
  height = 22,
}) => {
  const customSvg = useNormalizedBrandSvg('/brand/bale-logo.svg', height);

  if (customSvg) {
    return (
      <span
        className={`inline-flex items-center shrink-0 select-none ${className}`}
        style={{ height: `${height}px` }}
        aria-label="BALE"
        dangerouslySetInnerHTML={{ __html: customSvg }}
      />
    );
  }

  return (
    <span
      className={`inline-flex items-center justify-center px-2.5 py-1 rounded-xl bg-navy text-white font-black text-xs tracking-[0.18em] shadow-sm select-none ${className}`}
    >
      BALE
    </span>
  );
};
